#include <cuda_runtime.h>
#include <cstdio>
#include <vector>
#include "../.local/exclusive-scan-kernel.cuh"
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){printf("CUDA ERROR %s\n",cudaGetErrorString(e));return 2;}}while(0)
int scan(const unsigned int* input,unsigned int* output,unsigned int count,unsigned int* total){unsigned int groups=(count+511)/512,*sums;CHECK(cudaMalloc(&sums,groups*4));scanBlocks<<<groups,256>>>(input,output,sums,count);CHECK(cudaGetLastError());if(groups>1){unsigned int* offsets;CHECK(cudaMalloc(&offsets,groups*4));if(scan(sums,offsets,groups,total))return 2;addScanOffsets<<<(count+255)/256,256>>>(output,offsets,count);CHECK(cudaGetLastError());CHECK(cudaFree(offsets));}else{CHECK(cudaMemcpy(total,sums,4,cudaMemcpyDeviceToDevice));}CHECK(cudaFree(sums));return 0;}
int main(){unsigned int sizes[]={1,2,511,512,513,4096,32768,262145};for(unsigned int count:sizes){std::vector<unsigned int> input(count),output(count);for(unsigned int i=0;i<count;i++)input[i]=(i*2654435761u)^0xa5a5a5a5u;unsigned int *a,*b,*total;CHECK(cudaMalloc(&a,count*4));CHECK(cudaMalloc(&b,count*4));CHECK(cudaMalloc(&total,4));CHECK(cudaMemcpy(a,input.data(),count*4,cudaMemcpyHostToDevice));if(scan(a,b,count,total))return 2;CHECK(cudaDeviceSynchronize());CHECK(cudaMemcpy(output.data(),b,count*4,cudaMemcpyDeviceToHost));unsigned int sum=0,actual;for(unsigned int i=0;i<count;i++){if(output[i]!=sum){printf("Mismatch at %u\n",i);return 3;}sum+=input[i];}CHECK(cudaMemcpy(&actual,total,4,cudaMemcpyDeviceToHost));if(actual!=sum)return 3;char path[128];snprintf(path,sizeof(path),"reports/exclusive-scan-native-%u.bin",count);FILE* f=fopen(path,"wb");if(!f)return 2;fwrite(output.data(),4,count,f);fclose(f);printf("PASS count=%u total=%u\n",count,sum);CHECK(cudaFree(a));CHECK(cudaFree(b));CHECK(cudaFree(total));}return 0;}
